// caller returns the authenticated identity or a Huma 401.
func caller(ctx context.Context) (*auth.Identity, error) {
	id, ok := auth.IdentityFrom(ctx)
	if !ok || id == nil {
		return nil, huma.Error401Unauthorized("authentication required")
	}
	return id, nil
}

// ownedNote loads a note and enforces that the caller owns it (or is admin).
func ownedNote(ctx context.Context, a *app.App, id string) (*resources.NoteResponse, *auth.Identity, error) {
	who, err := caller(ctx)
	if err != nil {
		return nil, nil, err
	}
	row, err := models.Notes(a).Find(ctx, id)
	if err != nil {
		return nil, nil, huma.Error500InternalServerError("get failed", err)
	}
	if row == nil {
		return nil, nil, huma.Error404NotFound("note not found")
	}
	if row.UserID != who.ID && !who.HasRole("admin") {
		return nil, nil, huma.Error404NotFound("note not found")
	}
	resp := resources.TransformNote(*row)
	return &resp, who, nil
}

func newShareSlug() string {
	b := make([]byte, 8)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

