// gfm renders Markdown and ugc sanitizes it (same pipeline as
// togo-framework/richtext, inlined because that plugin mounts routes at
// PriorityService which trips auth v0.8.0's late Router.Use).
var (
	gfm = goldmark.New()
	ugc = bluemonday.UGCPolicy()
)

func renderSafeHTML(md string) string {
	var buf bytes.Buffer
	if err := gfm.Convert([]byte(md), &buf); err != nil {
		return ""
	}
	return ugc.Sanitize(buf.String())
}

// hasTag reports whether the comma-separated tags column contains tag.
func hasTag(tags, tag string) bool {
	for _, t := range strings.Split(tags, ",") {
		if strings.EqualFold(strings.TrimSpace(t), tag) {
			return true
		}
	}
	return false
}
